/**
 * One keyset page of live (not archived) org ids, in id order. Pass the last
 * id of the previous page as `afterId` to continue; `null` starts from the top.
 */
export async function listLiveOrgIdsPage(
  afterId: OrgId | null,
  limit: number,
): Promise<readonly OrgId[]> {
  const rows = getDb()
    .select({ id: organizations.id })
    .from(organizations)
    .where(
      and(
        isNull(organizations.archivedAt),
        afterId === null ? undefined : gt(organizations.id, afterId),
      ),
    )
    .orderBy(asc(organizations.id))
    .limit(Math.max(1, limit))
    .all();

  return rows.map((row) => brandId<OrgId>(row.id));
}

/**
 * Walks every live org, one page at a time, so a sweep covers the whole
 * population however many workspaces there are — not just a fixed first batch.
 */
export async function* eachLiveOrgId(
  pageSize: number,
): AsyncGenerator<OrgId> {
  let afterId: OrgId | null = null;

  for (;;) {
    const page = await listLiveOrgIdsPage(afterId, pageSize);
    for (const orgId of page) yield orgId;
    if (page.length < pageSize) return;
    afterId = page[page.length - 1] ?? null;
  }
}

/** Every org the user still holds a live membership in. */

